-- 1. Profil Sekolah
INSERT INTO school_profiles ("id", "schoolName", "npsn", "accreditation", "address", "city", "province", "phone", "email", "principalName", "principalNip", "vision", "mission", "goals", "history", "heroHeadline", "heroSubheadline", "studentCount", "teacherCount", "classroomCount", "extracurricularCount", "updatedAt") VALUES ('default-profile', 'SD Negeri Harapan Bangsa (Sekolah Contoh)', '20109999 (Data Contoh)', 'A (Unggul)', 'Jl. Pendidikan Karakter No. 45, Kompleks Edukasi Bahagia', 'Kota Contoh', 'Provinsi Contoh', '(021) 555-0199', 'info@sdharapanbangsa.sch.id', 'Dra. Hj. Siti Rahmawati, M.Pd.', '19750512 200003 2 001 (Contoh)', 'Terwujudnya peserta didik yang beriman, berakhlak mulia, cerdas, berkarakter, kreatif, dan berwawasan lingkungan global.', '1. Menumbuhkembangkan keimanan dan ketakwaan melalui pembiasaan ibadah dan budi pekerti luhur.
2. Menyelenggarakan pembelajaran Kurikulum Merdeka yang aktif, inovatif, dan berpusat pada peserta didik.
3. Mengembangkan bakat, minat, dan potensi anak secara optimal melalui ragam ekstrakurikuler.
4. Membangun lingkungan sekolah yang ramah anak, inklusif, bersih, sehat, dan asri.
5. Meningkatkan kompetensi pendidik dan tenaga kependidikan secara berkelanjutan.', '1. Seluruh lulusan memiliki fondasi literasi dan numerasi yang kokoh serta berkarakter Pancasila.
2. Terciptanya suasana belajar yang membahagiakan (well-being anak terjamin).
3. Meraih prestasi di bidang akademik maupun non-akademik di tingkat kota, provinsi, dan nasional.', 'SD Negeri Harapan Bangsa didirikan sebagai wujud kepedulian terhadap pendidikan dasar bermutu di lingkungan masyarakat. Dari awal berdirinya dengan 6 rombongan belajar, kini sekolah telah berkembang menjadi institusi pendidikan ramah anak terkemuka dengan fasilitas pembelajaran modern dan tenaga pendidik berdedikasi tinggi.', 'Membentuk Generasi Cerdas, Berakhlak Mulia & Ceria', 'Pendidikan dasar ramah anak dengan pendekatan Kurikulum Merdeka yang menumbuhkan rasa ingin tahu, empati, dan kreativitas putra-putri Anda.', 500, 30, 22, 12, NOW()) ON CONFLICT (id) DO NOTHING;

