-- 3. Berita & Pengumuman
INSERT INTO news ("id", "title", "slug", "excerpt", "content", "coverImage", "category", "status", "isFeatured", "viewCount", "publishedAt", "createdAt", "updatedAt") VALUES ('c39881d4-bb27-4598-8765-b06d1125e312', 'Implementasi Program Pembiasaan Sarapan Bersama dan Gosok Gigi Sehat', 'pembiasaan-sarapan-bersama-dan-gosok-gigi-sehat', 'Mendukung program Gerakan Sekolah Sehat (GSS), sekolah mengadakan sarapan bergizi bersama setiap hari Rabu pagi.', 'Kesehatan anak adalah fondasi utama bagi optimalnya proses belajar. Setiap hari Rabu pagi, seluruh siswa berkumpul di pendopo sekolah membawa bekal sehat yang disiapkan dari rumah.

Dipandu oleh dokter kecil dari UKS dan guru kelas, para siswa belajar tentang piring gizi seimbang: karbohidrat, protein, sayuran, dan buah-buahan segar. Setelah sarapan bersama, kegiatan dilanjutkan dengan praktik menyikat gigi bersama dengan teknik yang benar. Program ini bertujuan menanamkan pola hidup bersih dan sehat (PHBS) seumur hidup.', 'https://images.unsplash.com/photo-1509062522246-3755977927d7?auto=format&fit=crop&w=800&q=80', 'Kesehatan', 'PUBLISHED', false, 0, NOW(), NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO news ("id", "title", "slug", "excerpt", "content", "coverImage", "category", "status", "isFeatured", "viewCount", "publishedAt", "createdAt", "updatedAt") VALUES ('8882f602-367c-41f2-8c05-0d1a8a5a1d69', 'Raih Medali Emas di Olimpiade Sains Tingkat Provinsi 2025', 'raih-medali-emas-olimpiade-sains-provinsi-2025', 'Ananda Muhammad Rizky Pratama, siswa kelas 5, mengharumkan nama sekolah dengan menyabet medali emas di bidang IPA.', 'Prestasi membanggakan kembali ditorehkan oleh peserta didik SD Negeri Harapan Bangsa. Muhammad Rizky Pratama berhasil meraih Medali Emas dalam ajang Olimpiade Sains Pelajar Sekolah Dasar Tingkat Provinsi.

Kompetisi yang diikuti oleh lebih dari 250 peserta perwakilan sekolah terbaik ini menguji pemahaman konsep IPA, eksperimen laboratorium mini, serta kemampuan analisis fenomena alam sekitar. Rizky mengaku sangat senang dan bersyukur atas bimbingan para guru serta dukungan penuh dari orang tuanya.

Semoga prestasi ini menjadi pemantik semangat bagi seluruh peserta didik lainnya untuk terus tekun belajar dan tidak takut mencoba tantangan baru.', 'https://images.unsplash.com/photo-1588072432836-e10032774350?auto=format&fit=crop&w=800&q=80', 'Prestasi', 'PUBLISHED', true, 0, NOW(), NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO news ("id", "title", "slug", "excerpt", "content", "coverImage", "category", "status", "isFeatured", "viewCount", "publishedAt", "createdAt", "updatedAt") VALUES ('4e1ec1f0-0d99-4673-9b53-60dc46e9a378', 'Gelar Karya P5: Siswa Tampilkan Kreativitas Pengolahan Sampah Organik', 'gelar-karya-p5-kreativitas-pengolahan-sampah', 'SD Negeri Harapan Bangsa sukses menyelenggarakan pameran Proyek Penguatan Profil Pelajar Pancasila bertema Gaya Hidup Berkelanjutan.', 'Pagi ini suasana halaman SD Negeri Harapan Bangsa dipenuhi sorak sorai dan decak kagum para orang tua serta tamu undangan. Melalui kegiatan Gelar Karya P5, siswa dari kelas 1 hingga kelas 6 memamerkan hasil karya proyek belajar selama satu semester.

Mulai dari pupuk kompos hasil sisa makanan kantin, kerajinan tangan dari kardus bekas, hingga bazar makanan tradisional yang dimasak bersama orang tua. Kepala Sekolah, Dra. Hj. Siti Rahmawati, menyampaikan bahwa kegiatan ini tidak semata-mata mencari hasil karya terbaik, tetapi menanamkan nilai gotong royong, nalar kritis, dan kepedulian terhadap kelestarian alam sejak dini.

"Kami sangat bangga melihat putra-putri kami berani menjelaskan proses pembuatan karyanya kepada setiap pengunjung yang datang. Ini adalah bukti nyata bahwa anak-anak belajar dengan bahagia dan bermakna," ungkap beliau.', 'https://images.unsplash.com/photo-1577896851231-70ef18881754?auto=format&fit=crop&w=800&q=80', 'Kegiatan', 'PUBLISHED', true, 0, NOW(), NOW(), NOW()) ON CONFLICT (id) DO NOTHING;

